mapper.update:
UPDATE sys_menu
parent_id = #{parentId}, menu_type = #{menuType}, menu_name = #{menuName}, name_i18n = #{nameI18n}, route_name = #{routeName}, route_path = #{routePath}, component_path = #{componentPath}, permission_code = #{permissionCode}, icon = #{icon}, sort_no = #{sortNo}, visible = #{visible}, status = #{status}, is_external = #{isExternal}, is_cache = #{isCache}, remark = #{remark}, assign_scope = #{assignScope}, product_code = #{productCode}, updated_by = #{updatedBy}, updated_at = #{updatedAt}, deleted = #{deleted}
WHERE id = #{id} AND deleted = 0

mapper.select:
SELECT DISTINCT permission_code FROM sys_menu WHERE deleted = 0 AND status = '0' AND permission_code IS NOT NULL AND permission_code != ''
AND id NOT IN #{menuId}
ORDER BY permission_code

SELECT id FROM sys_menu WHERE deleted = 0 AND status = '0'
AND id NOT IN #{menuId}
ORDER BY sort_no ASC, id ASC

SELECT COUNT(1) FROM sys_menu
WHERE deleted = 0 AND assign_scope = #{assignScope}
  AND id IN #{menuId}

SELECT id FROM sys_menu
WHERE deleted = 0 AND status = '0' AND assign_scope = #{assignScope}
ORDER BY sort_no ASC, id ASC

SELECT COUNT(1) FROM sys_menu
WHERE deleted = 0 AND parent_id = '0' AND menu_type = 'M'
  AND product_code = #{productCode}

    AND id != #{excludeId}
